<?php

// phpcs:ignoreFile

/**
 * @file
 * Settings for a Domain Investors site.
 *
 * Committed with the project, and the same in every environment: nothing in
 * here is a secret or differs between one environment and another. What does
 * differ comes from the files included at the end:
 *
 * - settings.portfolio.php: payment gateway credentials, from environment
 *   variables (committed; it holds variable names, never values).
 * - settings.ddev.php: the database and hash salt under DDEV (generated by
 *   DDEV, not committed).
 * - settings.local.php: anything for one machine only (not committed).
 * - settings.vallic.php: the database, hash salt, files, trusted hosts, cache,
 *   mail and services.yml on Vallic Cloud (committed; inert anywhere else).
 *
 * A database or hash salt set nowhere else goes in settings.local.php, never
 * here. The installer appends both to this file when it has to ask for a
 * database; keep that change out of commits.
 */

$databases = [];

// Exported configuration, deployed with the code and imported by
// `drush deploy`.
$settings['config_sync_directory'] = '../config/sync';

// Private files, outside the document root. Vallic Cloud mounts its own.
$settings['file_private_path'] = '../private';

$settings['update_free_access'] = FALSE;
$settings['file_scan_ignore_directories'] = [
  'node_modules',
  'bower_components',
];
$settings['entity_update_batch_size'] = 50;
$settings['entity_update_backup'] = TRUE;
$settings['migrate_node_migrate_type_classic'] = FALSE;

// Payment gateway credentials, from environment variables.
if (file_exists($app_root . '/' . $site_path . '/settings.portfolio.php')) {
  include $app_root . '/' . $site_path . '/settings.portfolio.php';
}

// DDEV: database, hash salt and trusted hosts for the local project.
if (getenv('IS_DDEV_PROJECT') === 'true' && file_exists($app_root . '/' . $site_path . '/settings.ddev.php')) {
  include $app_root . '/' . $site_path . '/settings.ddev.php';
}

// This machine only: never committed.
if (file_exists($app_root . '/' . $site_path . '/settings.local.php')) {
  include $app_root . '/' . $site_path . '/settings.local.php';
}

// Vallic Cloud: database, files, hash salt, trusted hosts, Redis, mail and the
// project's own platform wiring. Last, so it wins; inert outside the platform.
if (file_exists($app_root . '/' . $site_path . '/settings.vallic.php')) {
  include $app_root . '/' . $site_path . '/settings.vallic.php';
}
